'use strict';
const $ = selector => document.querySelector(selector);
const labels = {supplier_purchase:'پارەدانی کڕین',supplier_payment:'پارەدان بە دابینکەر',supplier_refund:'پارەی گەڕاوە لە دابینکەر',sale:'پارەی فرۆشتن',repayment:'وەرگرتنەوەی قەرز',refund:'پارەی گەڕێندراوە بۆ کڕیار',deposit:'پارەخستنە سندوق',withdrawal:'پارەوەرگرتن لە کاشێر',expense:'پارە سەرفکردن'};
const format = value => new Intl.NumberFormat('en-US').format(typeof value==='string'&&/^-?\d+$/.test(value)?BigInt(value):value);
const date = value => new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'medium'}).format(new Date(value));
const key = 'kashier.cash-draft.v1.' + (KashierData.userId() || 'local');
let page=0,filter='',requestNumber=0,posting=null,busy=false,detail=null,blocked=false;
const journalWarning='تۆماری پارێزراوی مامەڵە نەخوێندرایەوە؛ بۆ ڕێگریکردن لە دووبارەبوونەوە، مامەڵەی نوێ وەستێنرا. پەیوەندی بە پشتگیری بکە.';
function node(tag,text){const element=document.createElement(tag);if(text!==undefined)element.textContent=text;return element;}
function status(selector,text){if(blocked&&(selector==='#cash-status'||selector==='#cash-form-status'))text=journalWarning;$(selector).textContent=text;$(selector).hidden=!text;}
function save(){if(blocked)return false;try{const raw=JSON.stringify({version:1,posting,kind:$('#cash-kind').value,amount:$('#cash-amount').value,note:$('#cash-note').value});sessionStorage.setItem(key,raw);if(sessionStorage.getItem(key)!==raw)throw Error('journal not saved');return true;}catch{status('#cash-form-status','پاراستنی ناسنامەی مامەڵە نەکرا؛ مامەڵەکە نەنێردرا.');return false;}}
function controls(){for(const input of document.querySelectorAll('[data-cash-lock]'))input.disabled=blocked||Boolean(posting);$('#cash-close').disabled=busy;$('#cash-submit').disabled=busy||blocked;$('#cash-submit').textContent=busy?'تۆمارکردن…':posting?'پشکنینەوەی هەمان مامەڵە':'تۆمارکردن';$('#cash-retry').hidden=blocked||!posting;$('#cash-form-help').textContent=posting?'دۆخی مامەڵەکە دەبێت پشتڕاست بکرێتەوە. هەمان ناسنامە بەکاردەهێنرێتەوە بۆ ڕێگری لە دووبارەبوون.':'ئەم مامەڵەیە پارەی بەردەستی سندوق دەگۆڕێت و تۆمارەکە دەپارێزرێت.';}
function openForm(kind){if(blocked){status('#cash-status',journalWarning);return;}if(!posting&&kind){if($('#cash-kind').value!==kind){$('#cash-amount').value='';$('#cash-note').value='';}$('#cash-kind').value=kind;}$('#cash-form-title').textContent=posting?'پشکنینەوەی مامەڵەی پارە':labels[$('#cash-kind').value];controls();$('#cash-form-dialog').showModal();}
function entryContent(entry){const section=node('div');section.append(node('h2',labels[entry.kind]||entry.kind),node('p','تۆماری C-'+entry.movement_no),node('p',date(entry.created_at)),node('p','بڕ: '+format(entry.amount)+' دینار'),node('p','گۆڕانی سندوق: '+(entry.delta>0?'+':'')+format(entry.delta)+' دینار'),node('p','پارەی دوای مامەڵە: '+format(entry.balance_after)+' دینار'));if(entry.note)section.append(node('p','هۆکار: '+entry.note));if(entry.kind==='refund')section.append(node('p','ئەم جووڵەیە لە گەڕاندنەوەی فرۆشتن دروست بووە؛ تۆماری فرۆشتنی سەرەکی ناسڕێتەوە.'));if(entry.kind==='supplier_refund')section.append(node('p','ئەم پارەیە لە گەڕاندنەوەی تەواوی کڕین لە دابینکەرەوە گەڕاوەتە قاسە؛ تۆماری کڕینی سەرەکی ناسڕێتەوە.'));section.append(node('p',entry.id));return section;}
function showDetail(entry){detail=entry;$('#cash-detail').replaceChildren(entryContent(entry));$('#cash-sale-link').hidden=!entry.sale_id&&!entry.customer_id&&!entry.supplier_id&&!entry.purchase_id;if(entry.purchase_id){$('#cash-sale-link').href='purchase-receipt.html?id='+entry.purchase_id;$('#cash-sale-link').textContent='پسوولەی کڕین';}else if(entry.supplier_id){$('#cash-sale-link').href='supplier.html?id='+entry.supplier_id;$('#cash-sale-link').textContent='حسابی دابینکەر';}else if(entry.sale_id){$('#cash-sale-link').href='receipt.html?id='+entry.sale_id;$('#cash-sale-link').textContent='پسوولەی فرۆشتن';}else if(entry.customer_id){$('#cash-sale-link').href='customer.html?id='+entry.customer_id;$('#cash-sale-link').textContent='حسابی کڕیار';}$('#cash-detail-dialog').showModal();}
async function load(){if(!KashierData.loggedIn()){location.replace('auth.html?next=cash.html');return false;}const request=++requestNumber;status('#cash-status','خوێندنەوەی تۆمارەکانی پارە…');$('#cash-previous').disabled=true;$('#cash-next').disabled=true;$('#cash-rows').replaceChildren();try{const [summary,result]=await Promise.all([KashierData.getCashSummary(),KashierData.listCashEntries(filter,page)]);if(request!==requestNumber)return false;for(const [selector,value]of [['#cash-balance',summary.balance],['#cash-sales',summary.sales],['#cash-refunds',summary.refunds??'0'],['#cash-supplier-purchases',summary.supplier_purchases??'0'],['#cash-supplier-payments',summary.supplier_payments??'0'],['#cash-supplier-refunds',summary.supplier_refunds??'0'],['#cash-deposits',summary.deposits],['#cash-withdrawals',summary.withdrawals],['#cash-expenses',summary.expenses],['#cash-repayments',summary.repayments??'0']])$(selector).textContent=format(value);for(const entry of result.rows){const row=node('tr');for(const value of ['C-'+entry.movement_no,date(entry.created_at),labels[entry.kind]||entry.kind])row.append(node('td',value));const delta=node('td',(entry.delta>0?'+':'')+format(entry.delta));delta.className=entry.delta>=0?'cash-delta-in':'cash-delta-out';row.append(delta,node('td',format(entry.balance_after)));const action=node('td'),button=node('button','وردەکاری');button.className='secondary';button.addEventListener('click',()=>showDetail(entry));action.append(button);row.append(action);$('#cash-rows').append(row);}$('#cash-count').textContent='تۆمار: '+result.total+' · پەڕە: '+(page+1);$('#cash-previous').disabled=page===0;$('#cash-next').disabled=(page+1)*50>=result.total;status('#cash-status',result.rows.length?'':'هێشتا هیچ مامەڵەیەک لەم لیستە تۆمار نەکراوە.');return true;}catch(error){if(request===requestNumber)status('#cash-status',error.message);return false;}}
for(const button of document.querySelectorAll('[data-cash-action]'))button.addEventListener('click',()=>openForm(button.dataset.cashAction));
$('#cash-close').addEventListener('click',()=>{if(!busy)$('#cash-form-dialog').close();});$('#cash-form-dialog').addEventListener('cancel',event=>{if(busy)event.preventDefault();});$('#cash-retry').addEventListener('click',()=>openForm());
for(const selector of ['#cash-kind','#cash-amount','#cash-note'])$(selector).addEventListener('input',()=>{if(!posting){save();$('#cash-form-title').textContent=labels[$('#cash-kind').value];}});
$('#cash-form').addEventListener('submit',async event=>{event.preventDefault();if(busy||blocked)return;if(!posting&&!KashierData.loggedIn()){location.href='auth.html?next=cash.html';return;}if(!posting){if(!$('#cash-form').reportValidity())return;try{const amount=SaleMath.money($('#cash-amount').value);if(amount<1)throw new Error('بڕی پارە دەبێت زیاتر لە سفر بێت.');const note=$('#cash-note').value.trim();if(!note)throw new Error('هۆکاری مامەڵە بنووسە.');const id=crypto.randomUUID();posting={id,payload:{p_id:id,p_kind:$('#cash-kind').value,p_amount:amount,p_note:note}};if(!save()){posting=null;controls();return;}}catch(error){status('#cash-form-status',error.message);return;}}
 busy=true;controls();status('#cash-form-status','تۆمارکردنی مامەڵە…');try{const entry=await KashierData.postCashEntry(posting.payload);if(entry?.id!==posting.id)throw new Error('وەڵامی مامەڵە پشتڕاست نەکرایەوە.');posting=null;try{sessionStorage.removeItem(key);}catch{}$('#cash-amount').value='';$('#cash-note').value='';$('#cash-form-dialog').close();page=0;const refreshed=await load();if(refreshed)status('#cash-status','مامەڵەکە تۆمار کرا.');showDetail(entry);}catch(error){if([400,401,403,422].includes(error.status)&&error.saleCode!=='cash_request_conflict'){posting=null;save();status('#cash-form-status',error.message);}else{save();status('#cash-form-status','دۆخی مامەڵە هێشتا پشتڕاست نییە؛ هەمان مامەڵە دووبارە بپشکنەوە.');}}finally{busy=false;controls();}});
$('#cash-detail-close').addEventListener('click',()=>$('#cash-detail-dialog').close());$('#cash-print').addEventListener('click',()=>{if(!detail)return;$('#print-area').replaceChildren(node('h1','کاشێر'),entryContent(detail));window.print();});
$('#cash-refresh').addEventListener('click',load);$('#cash-filter').addEventListener('change',()=>{filter=$('#cash-filter').value;page=0;load();});$('#cash-previous').addEventListener('click',()=>{if(page>0){page--;load();}});$('#cash-next').addEventListener('click',()=>{page++;load();});
try{const raw=sessionStorage.getItem(key);if(raw!==null){const draft=JSON.parse(raw);if(!draft||Array.isArray(draft)||draft.version!==1||!['deposit','withdrawal','expense'].includes(draft.kind)||typeof draft.amount!=='string'||typeof draft.note!=='string'||!Object.hasOwn(draft,'posting'))throw Error('Invalid draft');if(draft.posting!==null){const p=draft.posting,payload=p?.payload;if(!p||! /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(p.id)||payload?.p_id!==p.id||payload.p_kind!==draft.kind||!Number.isSafeInteger(payload.p_amount)||payload.p_amount<1||payload.p_amount!==SaleMath.money(draft.amount)||typeof payload.p_note!=='string'||!payload.p_note.trim()||payload.p_note!==draft.note.trim()||payload.p_note.length>500)throw Error('Invalid pending request');}$('#cash-kind').value=draft.kind;$('#cash-amount').value=draft.amount;$('#cash-note').value=draft.note;posting=draft.posting;}}catch{blocked=true;status('#cash-status',journalWarning);}
controls();if(KashierData.loggedIn()){load();const kind=new URLSearchParams(location.search).get('kind');if(posting)openForm();else if(['deposit','withdrawal','expense'].includes(kind))openForm(kind);}else location.replace('auth.html?next='+encodeURIComponent('cash.html'+location.search));
